ee:message.ee:set-payload:
%dw 2.0
output application/xml encoding= "UTF-8"
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
---
soapenv#Envelope @("xmlns:tem": "http://tempuri.org/", 
        "xmlns:tier": "http://schemas.datacontract.org/2004/07/Tier.Common", 
        "xmlns:ws":   "http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts"
        ): {
            soapenv#Header: null,
            soapenv#Body: {
                tem#RespuestaTransaccion: {
                    tem#WSRequestHeader: {
                        tier#property: {
                            tier#"Scheme_Services.Property": {
                                tier#name: "?",
                                tier#value: "?"
                            }
                        },
                        tier#system: {
                            tier#correlationId: vars.inputBody.respuestaViabilidad.correlationId,
                            tier#name: "?",
                            tier#processingServer: "?"
                        }
                    },
                    tem#WSRequestBody: {
                        ws#Descripcion: "Los siguientes items presentan errores: " ++  (vars.itemsWithError joinBy(", ")),
                        ws#Fecha: now(),
                        ws#NumeroSolicitud: vars.inputBody.respuestaViabilidad.idViabilidad,
                        ws#OrdenOM: vars.inputBody.respuestaViabilidad.ordenOM,
                        ws#Productos: vars.inputBody.respuestaViabilidad.productos,
                        ws#Resultado: false,
                        ws#TipoSolicitud: vars.responseOrderById.resultados[0].tipoSolicitud,
                        ws#TipoSolicitud: "CERRAR"
                    }
                }
            }
        }

%dw 2.0
output application/java
---
{
	"msgError": "Alguno de los items presenta un error"
}

%dw 2.0
import * from dw::util::Values
output application/json
fun updateItemsEmpty(obj: Object, idViabilidad: String) =
    obj.items map ( (item, index) ->
    if( idViabilidad  == (item.idOrigen) )
    (
    	if (item.RESPUESTA_RECIBIDA != null ) (item update "RESPUESTA_RECIBIDA" with 1)
		else (item ++ "RESPUESTA_RECIBIDA": 1)
	 ) else item )
---
vars.responseOrderById.resultados[0] update "items" with  updateItemsEmpty(vars.responseOrderById.resultados[0], vars.inputBody.respuestaViabilidad.idViabilidad)

%dw 2.0
output application/java
---
{
	"msgError": "No se encontró una orden con ese id."
}

%dw 2.0
output application/json
import util::GlobalFunctions as global
import * from dw::util::Values
---
if (vars.orderState == "OR0020"){
			"estadoOrden": {
			"fecha": now(),
			"codigoEstado": "OR0020",
			"nombreEstado": "EN_PROCESO",
			"observaciones": "EN_PROCESO"
			}
		}
else if (vars.orderState == "OR0021") {
			"estadoOrden": {
			"fecha": now(),
			"codigoEstado": "OR0021",
			"nombreEstado": "ERROR_VALIDACION",
			"observaciones": "ERROR_VALIDACION"
			}
		}
else if (vars.orderState == "OR0060" and vars.inputBody.respuestaViabilidad.productos != null ) global::updateOrderState( (payload update "items" with  global::updateItemsState(payload,vars.itemsToBeUpdated,"ITM30","RESPUESTA_BACK_PROCESADA")),"OR0020","EN_PROCESO")
else null
